{
  "claims": [
    {
      "claim_text": "Because the wal-index lives in shared memory, all processes using a WAL database must be on the same host, so two processes on different machines sharing a database over NFS cannot use WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] states all processes must be on the same host and WAL does not work over a network filesystem; passage [1] attributes this to the shared-memory wal-index.",
      "citations": [
        {"index": 0, "quote": "All processes using a database must be on the same host computer; WAL does not work over a network filesystem."},
        {"index": 1, "quote": "The wal-index greatly improves the performance of readers, but the use of shared memory means that all readers must exist on the same machine. This is why the write-ahead log implementation will not work on a network filesystem."}
      ]
    },
    {
      "claim_text": "Being on the same host, however, is enough to guarantee that WAL will work.",
      "verdict": "CONTRADICTED",
      "reasoning": "The passages present same-host as a necessary condition, not a sufficient one. Passage [5] states that the underlying VFS must also support version 2 shared-memory methods, otherwise opening or converting a WAL database fails (absent EXCLUSIVE mode). Thus same host alone does not guarantee WAL will work.",
      "citations": [
        {"index": 5, "quote": "This means that the underlying VFS must support the \"version 2\" shared-memory. If the VFS does not support shared-memory methods, then the attempt to open a database that is already in WAL mode, or the attempt to convert a database into WAL mode, will fail."}
      ]
    },
    {
      "claim_text": "Since there is only one WAL file, two writers can never be writing at the same moment, even though readers can run alongside a writer.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] states there can only be one writer at a time because there is only one WAL file, and that writers and readers can run at the same time.",
      "citations": [
        {"index": 2, "quote": "However, since there is only one WAL file, there can only be one writer at a time."},
        {"index": 2, "quote": "Because writers do nothing that would interfere with the actions of readers, writers and readers can run at the same time."}
      ]
    },
    {
      "claim_text": "This single-writer limit can be lifted with BEGIN CONCURRENT.",
      "verdict": "UNSUPPORTED",
      "reasoning": "BEGIN CONCURRENT is never mentioned in any of the passages.",
      "citations": []
    },
    {
      "claim_text": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] states WAL databases can be accessed without shared memory as long as locking_mode is set to EXCLUSIVE before the first attempted access; passage [5] confirms the wal-index is omitted only when locking mode is EXCLUSIVE prior to the first WAL-mode access.",
      "citations": [
        {"index": 3, "quote": "WAL databases can be created, read, and written even if shared memory is unavailable as long as the locking_mode is set to EXCLUSIVE before the first attempted access."},
        {"index": 5, "quote": "It is only when the shared-memory wal-index is omitted, when the locking mode is EXCLUSIVE prior to the first WAL-mode database access, that the locking mode is stuck in EXCLUSIVE."}
      ]
    },
    {
      "claim_text": "In that case it stays in EXCLUSIVE mode until it leaves WAL journal mode.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states the connection remains in EXCLUSIVE mode as long as the journal mode is WAL and the only way out is to first change out of WAL journal mode.",
      "citations": [
        {"index": 4, "quote": "In that case, the database connection remains in EXCLUSIVE mode as long as the journal mode is WAL; attempts to change the locking mode using \"PRAGMA locking_mode=NORMAL;\" are no-ops. The only way to change out of EXCLUSIVE locking mode is to first change out of WAL journal mode."}
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [6] states writers omit the WAL sync when PRAGMA synchronous is set to NORMAL.",
      "citations": [
        {"index": 6, "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL but omit this sync if PRAGMA synchronous is set to NORMAL."}
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, the checkpoint is the only operation that issues a sync.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [7] states this verbatim.",
      "citations": [
        {"index": 7, "quote": "Note that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation (fsync() on unix or FlushFileBuffers() on windows)."}
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=FULL, every commit syncs the WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [6] states writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL.",
      "citations": [
        {"index": 6, "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL but omit this sync if PRAGMA synchronous is set to NORMAL."}
      ]
    },
    {
      "claim_text": "Running the checkpoint in a separate thread therefore guarantees that the main thread never blocks on a sync, whatever the synchronous setting.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [7]'s statement that the main thread never blocks on a sync is explicitly conditioned on PRAGMA synchronous being NORMAL. With synchronous=FULL, passage [6] says writers sync the WAL on every transaction commit, so the main thread would still perform syncs. The claim's 'whatever the synchronous setting' is refuted.",
      "citations": [
        {"index": 7, "quote": "Note that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation (fsync() on unix or FlushFileBuffers() on windows). If an application therefore runs checkpoint in a separate thread or process, the main thread or process that is doing database queries and updates will never block on a sync operation."},
        {"index": 6, "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL but omit this sync if PRAGMA synchronous is set to NORMAL."}
      ]
    }
  ]
}

{
  "claims": [
    {
      "claim_text": "ANALYZE gathers the statistics the query planner relies on.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] states the query planner relies on statistical information and that these statistics are gathered by the ANALYZE command.",
      "citations": [
        {
          "index": 0,
          "quote": "The PostgreSQL query planner relies on statistical information about the contents of tables in order to generate good plans for queries. These statistics are gathered by the ANALYZE command"
        }
      ]
    },
    {
      "claim_text": "ANALYZE can run on its own or as an optional step in VACUUM.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] explicitly states ANALYZE can be invoked by itself or as an optional step in VACUUM.",
      "citations": [
        {
          "index": 0,
          "quote": "which can be invoked by itself or as an optional step in VACUUM"
        }
      ]
    },
    {
      "claim_text": "ANALYZE samples rows randomly instead of reading every row.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states ANALYZE uses a statistically random sampling rather than reading every row.",
      "citations": [
        {
          "index": 4,
          "quote": "ANALYZE uses a statistically random sampling of the rows of a table rather than reading every single row."
        }
      ]
    },
    {
      "claim_text": "It is usually best to just analyze the whole database.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states that in practice it is usually best to analyze the entire database because it is fast.",
      "citations": [
        {
          "index": 4,
          "quote": "In practice, however, it is usually best to just analyze the entire database, because it is a fast operation."
        }
      ]
    },
    {
      "claim_text": "By default ANALYZE samples 30,000 rows per table.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage mentions any specific default sample size such as 30,000 rows.",
      "citations": []
    },
    {
      "claim_text": "The autovacuum daemon schedules ANALYZE purely as a function of the number of rows inserted or updated.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] states this directly.",
      "citations": [
        {
          "index": 1,
          "quote": "The daemon schedules ANALYZE strictly as a function of the number of rows inserted or updated"
        }
      ]
    },
    {
      "claim_text": "Autovacuum may skip a table whose statistical distribution changed meaningfully if only a few rows were touched.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] says scheduling is strictly a function of row counts and the daemon has no knowledge of whether changes lead to meaningful statistical changes, which entails that few row changes will not trigger ANALYZE even if statistics meaningfully changed.",
      "citations": [
        {
          "index": 1,
          "quote": "it has no knowledge of whether that will lead to meaningful statistical changes."
        }
      ]
    },
    {
      "claim_text": "Changes to partitions or inheritance children do not trigger autoanalyze on the parent table.",
      "verdict": "SUPPORTED",
      "reasoning": "Passages [2] and [6] both state that changes to partitions/child tables do not trigger analyze on the parent.",
      "citations": [
        {
          "index": 2,
          "quote": "Tuples changed in partitions and inheritance children do not trigger analyze on the parent table."
        },
        {
          "index": 6,
          "quote": "changes to child tables do not trigger autoanalyze on the parent table."
        }
      ]
    },
    {
      "claim_text": "An inheritance parent is never analyzed by autovacuum.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [6] states inheritance parents ARE analyzed if the parent itself is changed, and passage [2] only says it 'may never' be processed if empty or rarely changed — not that it is never analyzed.",
      "citations": [
        {
          "index": 6,
          "quote": "Inheritance parents will only be analyzed if the parent itself is changed"
        },
        {
          "index": 2,
          "quote": "If the parent table is empty or rarely changed, it may never be processed by autovacuum"
        }
      ]
    },
    {
      "claim_text": "Autovacuum runs ANALYZE on a partitioned table only after its partitions change significantly.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passages [6] and [7] state autovacuum does not issue ANALYZE commands for partitioned tables at all; manual ANALYZE is required.",
      "citations": [
        {
          "index": 6,
          "quote": "The autovacuum daemon does not issue ANALYZE commands for partitioned tables."
        },
        {
          "index": 7,
          "quote": "autovacuum does not run ANALYZE on partitioned tables"
        }
      ]
    },
    {
      "claim_text": "A timestamp column that records each row's update time will probably need more frequent statistics updates than a column of URLs.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] makes exactly this comparison.",
      "citations": [
        {
          "index": 3,
          "quote": "a timestamp column that contains the time of row update will have a constantly-increasing maximum value as rows are added and updated; such a column will probably need more frequent statistics updates than, say, a column containing URLs for pages accessed on a website."
        }
      ]
    }
  ]
}
